sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 position;
uniform float radius;
uniform float brightness;
uniform float shine;
layout(color) uniform half4 color;
uniform float points;
uniform float alpha;
uniform float blend;
uniform float edgeStyle;
float3 blendWith(float m, float3 b, float3 s) {
    if (m < 0.5) return s;
    if (m < 1.5) return b * s;
    if (m < 2.5) return b + s - b * s;
    if (m < 3.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, b));
    if (m < 4.5) {
        float3 d = mix(sqrt(b), ((16.0 * b - 12.0) * b + 4.0) * b, step(b, float3(0.25)));
        return mix(b - (1.0 - 2.0 * s) * b * (1.0 - b), b + (2.0 * s - 1.0) * (d - b), step(0.5, s));
    }
    if (m < 5.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, s));
    if (m < 6.5) return min(b + s, 1.0);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return max(b, s);
    if (m < 9.5) return abs(b - s);
    if (m < 10.5) return min(b / max(1.0 - s, 0.0001), 1.0);
    return 1.0 - min((1.0 - b) / max(s, 0.0001), 1.0);
}
half4 standard(float2 coord, half4 src) {
    float2 p = coord - position * size;
    float r = length(p) / max(radius * 0.5 * min(size.x, size.y), 0.0001);
    float n = max(points, 1.0);
    float sector = 6.2831853 / n;
    float t = (dot(p, p) > 0.0 ? atan(p.y, p.x) : 0.0) + 1.5707963;
    float tc = mod(-t, 6.2831853);
    float dl = tc - sector * floor(tc / sector + 0.5);
    float d5 = dl * n / 5.0;
    float u = r * cos(d5);
    float v = r * abs(sin(d5));
    float ts = shine + 0.1;
    float g = exp(5.0584 * ts + 2.1629 * (shine * shine - 0.01));
    float hl = 0.19355 * clamp(1.0 + 0.9497 * ts, 0.739, 1.2323);
    float e = sqrt(pow((u - hl) / hl, 2.0) + pow(v / (0.04 * max(1.0 + 3.029 * ts, 0.001)), 2.0));
    float petal = u > -0.05 ? min(4.2448 * g / (1.0 + exp(min((e - 1.0) / 0.6849, 60.0))), 1.0) : 0.0;
    float lobe = pow(cos(dl * n * 0.5) * cos(dl * n * 0.5), 6.6519);
    float lam = 0.2943 * (ts > 0.0 ? 0.7948 + 0.2052 * exp(-ts / 0.096) : 1.0);
    float halo = min(4.9445 * g * exp(-r / lam) * (0.3162 + 0.6838 * lobe), 1.0);
    float cw = 0.6262 * (1.0 + 0.0684 * clamp(-ts * 20.0, 0.0, 1.0));
    float core = min(0.7068 * g * exp(-(r / cw) * (r / cw)), 1.0);
    float a = (1.0 - (1.0 - petal) * (1.0 - core) * (1.0 - halo)) * clamp((1.96 - r) * radius * 0.5 * min(size.x, size.y) + 0.5, 0.0, 1.0);
    float3 tint = float3(color.rgb) / max(float(color.a), 0.0001);
    float3 f = a * min(max(brightness, 0.0) * a * 0.9388 * (tint + 0.206), 1.0);
    float3 base = float3(src.rgb) / float(src.a);
    float3 lit = blend < 0.5 ? min(f + base * (1.0 - a), 1.0) : blend < 1.5 ? base * f : clamp(blendWith(blend, base, f), 0.0, 1.0);
    return half4(half3(mix(base, lit, clamp(alpha, 0.0, 1.0))) * src.a, src.a);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    if (edgeStyle > 0.5) return standard(coord, src);
    float2 p = coord - position * size;
    float r = length(p) / max(radius * 0.5 * min(size.x, size.y), 0.0001);
    float t = (dot(p, p) > 0.0 ? atan(p.y, p.x) : 0.0) + 1.5707963;
    float spike = pow(0.5 + 0.5 * cos(floor(points + 0.5) * t), 2.0);
    float rr = r / mix(0.12, 1.0, spike);
    float g = brightness / 3.0 * (1.8 * exp(-3.0 * rr) + 0.45 * exp(-2.0 * r / max(1.0 + shine, 0.05)));
    float3 glow = float3(color.rgb) * min(g, 1.0) + float3(max(g - 1.0, 0.0));
    float amount = clamp(alpha, 0.0, 1.0) * float(color.a);
    float3 base = float3(src.rgb) / float(src.a);
    float cover = clamp(g, 0.0, 1.0);
    float3 mixed = blend > 5.5 && blend < 6.5 ? min(base + glow, 1.0) : mix(base, clamp(blendWith(blend, base, clamp(glow, 0.0, 1.0)), 0.0, 1.0), cover);
    return half4(half3(mix(base, mixed, amount)) * src.a, src.a);
}
